def transform(grid):
    """Draw color 3 between consecutive occurrences of the rare marker, in rows and columns."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    if not h or not w:
        return []

    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    marker = min(counts, key=counts.get)

    out = [row[:] for row in grid]
    for r in range(h):
        positions = [c for c, value in enumerate(grid[r]) if value == marker]
        for a, b in zip(positions, positions[1:]):
            for c in range(a + 1, b):
                out[r][c] = 3

    for c in range(w):
        positions = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(positions, positions[1:]):
            for r in range(a + 1, b):
                out[r][c] = 3

    return out

